const input = $input.first().json;
const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});

// Código completo do formulário com correções do debug-local
const code = `export default async function ({ page }) {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};
  let debug = [];

  try {
    await page.setViewport({ width: 1280, height: 800 });

    // Restaura sessão e vai para página do Hapvida
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 60000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => {
      for (const [key, value] of Object.entries(ls)) window.localStorage.setItem(key, value);
    }, ls);
    await page.reload({ waitUntil: 'domcontentloaded', timeout: 60000 });
    await wait(4000);
    debug.push('Pagina carregada');

    // Clica em PME
    const pmeClicked = await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) { pme.click(); return true; }
      return false;
    });
    debug.push('PME: ' + pmeClicked);
    await wait(2000);

    // Preenche nome
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) {
      await nomeInput.click();
      await wait(300);
      await nomeInput.type('teste', { delay: 30 });
      debug.push('Nome preenchido');
    }

    // Clica Avancar 1
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(3000);
    debug.push('Avancar 1');

    // Preenche cidade - digita teresina
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) {
      await cidadeInput.click();
      await wait(500);
      await cidadeInput.type('teresina', { delay: 100 });
    }
    await wait(2000);

    // Clica na cidade usando coordenadas (correção do debug-local)
    const teresinaCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        if (el.textContent.trim() === 'Teresina - PI') {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });

    if (teresinaCoords) {
      await page.mouse.click(teresinaCoords.x, teresinaCoords.y);
      debug.push('Cidade clicada via mouse');
    } else {
      debug.push('Cidade NAO encontrada');
    }
    await wait(2000);

    // Seleciona empresa MEI
    try {
      await page.waitForSelector('select.Dropdown', { timeout: 5000 });
      await page.click('select.Dropdown');
      await wait(500);
      await page.select('select.Dropdown', '"mei___empres_rio_individual"');
      debug.push('MEI selecionado');
    } catch(e) {
      debug.push('MEI erro: ' + e.message);
    }
    await wait(1500);

    // Clica Avancar 2 - botão VISÍVEL (há 2, um escondido)
    const buttons2 = await page.$$('button');
    for (const btn of buttons2) {
      const info = await page.evaluate(el => {
        const style = window.getComputedStyle(el);
        return { text: el.textContent, display: style.display, visibility: style.visibility };
      }, btn);
      if (info.text && info.text.includes('Avan') && info.display !== 'none' && info.visibility !== 'hidden') {
        await btn.click();
        debug.push('Avancar 2');
        break;
      }
    }
    await wait(3000);

    // FAIXAS ETÁRIAS - preenche APENAS inputs com placeholder='0' e classe 'cocys'
    const faixasResult = await page.evaluate(() => {
      const allInputs = document.querySelectorAll('input');
      let count = 0;
      [...allInputs].forEach((inp) => {
        const rect = inp.getBoundingClientRect();
        const style = window.getComputedStyle(inp);
        const isVisible = rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
        const isFaixaInput = inp.placeholder === '0' && inp.className.includes('cocys');
        if (isVisible && !inp.id && isFaixaInput) {
          inp.focus();
          inp.value = '1';
          inp.dispatchEvent(new Event('input', { bubbles: true }));
          inp.dispatchEvent(new Event('change', { bubbles: true }));
          count++;
        }
      });
      return count;
    });
    debug.push('Faixas preenchidas: ' + faixasResult);
    await wait(1500);

    // Clica Avancar 3 - botão VISÍVEL
    const buttons3 = await page.$$('button');
    for (const btn of buttons3) {
      const info = await page.evaluate(el => {
        const style = window.getComputedStyle(el);
        return { text: el.textContent, display: style.display, visibility: style.visibility };
      }, btn);
      if (info.text && info.text.includes('Avan') && info.display !== 'none' && info.visibility !== 'hidden') {
        await btn.click();
        debug.push('Avancar 3');
        break;
      }
    }
    await wait(4000);

    // Clica em Add Produtos - botão VISÍVEL
    const buttons4 = await page.$$('button');
    for (const btn of buttons4) {
      const info = await page.evaluate(el => {
        const style = window.getComputedStyle(el);
        return { text: el.textContent.trim(), display: style.display, visibility: style.visibility };
      }, btn);
      if (info.text === 'Add Produtos' && info.display !== 'none' && info.visibility !== 'hidden') {
        await btn.click();
        debug.push('Add Produtos');
        break;
      }
    }
    await wait(3000);

    // Clica em Hapvida (no modal)
    const hapvidaCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        if (el.textContent.trim() === 'Hapvida') {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });
    if (hapvidaCoords) {
      await page.mouse.click(hapvidaCoords.x, hapvidaCoords.y);
      debug.push('Hapvida clicado');
    }
    await wait(3000);

    // Clica na tabela Hapvida Teresina 2 a 29
    const tabelaCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        const text = el.textContent.trim();
        if (text.includes('Teresina') && text.includes('2') && text.includes('29')) {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });
    if (tabelaCoords) {
      await page.mouse.click(tabelaCoords.x, tabelaCoords.y);
      debug.push('Tabela Teresina clicada');
    }
    await wait(2000);

    // Clica em Ambulatorial
    const ambulatorialCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        if (el.textContent.trim() === 'Ambulatorial') {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });
    if (ambulatorialCoords) {
      await page.mouse.click(ambulatorialCoords.x, ambulatorialCoords.y);
      debug.push('Ambulatorial clicado');
    }
    await wait(2000);

    // Clica em Sem acomodação / Com coparticipação
    const acomodacaoCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        const text = el.textContent.trim().toLowerCase();
        if (text.includes('sem acomodação') && text.includes('coparticipação')) {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });
    if (acomodacaoCoords) {
      await page.mouse.click(acomodacaoCoords.x, acomodacaoCoords.y);
      debug.push('Acomodacao clicada');
    }
    await wait(2000);

    // Fecha o modal clicando em espaço vazio
    await page.mouse.click(1200, 400);
    debug.push('Modal fechado');
    await wait(3000);

    // EXTRAI OS VALORES DAS FAIXAS ETÁRIAS
    const dadosFaixas = await page.evaluate(() => {
      const isVisible = (el) => {
        const style = window.getComputedStyle(el);
        const rect = el.getBoundingClientRect();
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
      };

      const faixasNomes = ['0 a 18 anos', '19 a 23 anos', '24 a 28 anos', '29 a 33 anos', '34 a 38 anos', '39 a 43 anos', '44 a 48 anos', '49 a 53 anos', '54 a 58 anos', '59 anos ou mais'];
      const resultado = [];

      // Pega todos os valores numéricos únicos (preços)
      const allElements = document.querySelectorAll('div, span');
      const valoresUnicos = [];
      const valorRegex = /^\d{2,3}[,.]\d{2}$/;

      allElements.forEach((el) => {
        if (isVisible(el) && el.textContent.length < 15) {
          const text = el.textContent.trim();
          if (valorRegex.test(text) && !valoresUnicos.includes(text)) {
            const rect = el.getBoundingClientRect();
            // Só pega valores na área correta (coluna de preços, y > 650)
            if (rect.y > 650 && rect.x > 150 && rect.x < 280) {
              valoresUnicos.push({ text, y: rect.y });
            }
          }
        }
      });

      // Ordena por posição Y
      valoresUnicos.sort((a, b) => a.y - b.y);

      // Monta o resultado
      for (let i = 0; i < Math.min(faixasNomes.length, valoresUnicos.length); i++) {
        resultado.push({
          faixa_etaria: faixasNomes[i],
          valor: 'R$ ' + valoresUnicos[i].text.replace('.', ',')
        });
      }

      return resultado;
    });

    return { success: true, fase: 'COMPLETO', faixas: dadosFaixas, debug };
  } catch (error) {
    return { success: false, fase: 'ERRO', error: error.message, debug };
  }
}`;

return [{ json: { code } }];

const input = $input.first().json;

// Se deu erro, retorna o erro
if (!input.success) {
  return [{ json: { success: false, error: input.error, debug: input.debug } }];
}

// Retorna os dados das faixas em formato JSON
return [{ json: { 
  success: true, 
  faixas_etarias: input.faixas || [],
  debug: input.debug 
} }];
